#include "io.hpp"
#define main included_engine_main
#include "engine.hpp"
#undef main
void killcase(fs::path p,size_t done,int stage){size_t n=8192;{Engine e(p,n,true);for(size_t t=0;t<done;t++)e.commit(changes(t,MAX_GROUP,n));}pid_t pid=fork();need(pid>=0,"fork");if(!pid){Engine e(p,n,true);e.commit(changes(done,MAX_GROUP,n),stage);_exit(9);}int status;need(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&WEXITSTATUS(status)==40+stage,"crash stage");size_t recovered;{Engine e(p,n,true);auto old=expected(n,MAX_GROUP,done),next=expected(n,MAX_GROUP,done+1);if(stage==3||stage==14)need(e.rows==next,"acknowledged post-sync state");else if(stage==2||stage==12||stage==13)need(e.rows==old||e.rows==next,"uncertain atomic state");else need(e.rows==old,"prior acknowledged state");recovered=e.frontier/MAX_GROUP;need(e.frontier==recovered*MAX_GROUP&&(recovered==done||recovered==done+1),"exact logical frontier");e.commit(changes(recovered,MAX_GROUP,n));e.checkpoint();}{Engine e(p,n,true);need(e.frontier==(recovered+1)*MAX_GROUP&&e.rows==expected(n,MAX_GROUP,recovered+1),"continue checkpoint/reopen");}}
int main(int argc,char**argv){try{need(argc==2,"new root");fs::path root=argv[1];need(fs::create_directory(root),"fresh root");for(size_t done:{size_t(1),size_t(CAP)})for(int stage:{1,2,3,9,10,11,12,13,14})killcase(root/("d"+std::to_string(done)+"s"+std::to_string(stage)),done,stage);for(int stage=4;stage<=8;stage++)killcase(root/("checkpoint"+std::to_string(stage)),CAP,stage);
for(size_t copy=0;copy<2;copy++)for(size_t part=0;part<3;part++){auto p=root/("damage"+std::to_string(copy)+"-"+std::to_string(part));{Engine e(p,8192,true);e.commit(changes(0,MAX_GROUP,8192));}int f=open((p/"ring").c_str(),O_RDWR);need(f>=0,"open ring");size_t off=copy*SLOT+(part==0?8:part==1?sizeof(Head)+3:SLOT-sizeof(Tail)+8);char b;pr(f,&b,1,off);b^=1;pw(f,&b,1,off);close(f);{Engine e(p,8192,true);need(e.frontier==MAX_GROUP&&e.rows==expected(8192,MAX_GROUP,1),"single-copy damage");e.commit(changes(1,MAX_GROUP,8192));e.checkpoint();}{Engine e(p,8192,true);need(e.frontier==2*MAX_GROUP&&e.rows==expected(8192,MAX_GROUP,2),"damage continuation");}}
auto p=root/"multiple-wrap";size_t commits=3*CAP+19;{Engine e(p,8192,true);for(size_t t=0;t<commits;t++)e.commit(changes(t,MAX_GROUP,8192));auto gap=changes(commits,MAX_GROUP,8192);gap[0].id++;bool failed=false;try{e.commit(gap);}catch(...){failed=true;}need(failed&&e.frontier==commits*MAX_GROUP,"request gap rejection");}{Engine e(p,8192,true);need(e.rows==expected(8192,MAX_GROUP,commits)&&e.frontier==commits*MAX_GROUP,"multiwrap reopen");e.commit(changes(commits,MAX_GROUP,8192));e.checkpoint();}{Engine e(p,8192,true);need(e.rows==expected(8192,MAX_GROUP,commits+1),"multiwrap continuation");}
auto u=root/"sync-error";{Engine e(u,8192,true);bool failed=false;try{e.commit(changes(0,MAX_GROUP,8192),0,true);}catch(...){failed=true;}need(failed&&e.poison&&e.frontier==0&&e.rows==fixture(8192),"uncertain sync poisons before publication");failed=false;try{e.commit(changes(0,MAX_GROUP,8192));}catch(...){failed=true;}need(failed,"poison reuse");}{Engine e(u,8192,true);need(e.rows==fixture(8192)||e.rows==expected(8192,MAX_GROUP,1),"uncertain sync recovery");}
auto bad=root/"manifest-damage";{Engine e(bad,8192,true);e.commit(changes(0,MAX_GROUP,8192));}int f=open((bad/"manifest").c_str(),O_RDWR);char b;pr(f,&b,1,8);b^=1;pw(f,&b,1,8);close(f);bool failed=false;try{Engine e(bad,8192,true);}catch(...){failed=true;}need(failed,"manifest corruption rejection");if(VALUE_BANKS){auto q=root/"immutable-bad";{Engine e(q,8192,true);e.commit(changes(0,MAX_GROUP,8192));}int f=open((q/"immutable").c_str(),O_RDWR);char b;pr(f,&b,1,8);b^=1;pw(f,&b,1,8);close(f);bool rejected=false;try{Engine e(q,8192,true);}catch(...){rejected=true;}need(rejected,"immutable corruption rejection");}std::cout<<"PASS cap="<<MAX_GROUP<<" slot="<<SLOT<<" 23 early/mid-wrap/checkpoint exits,6single-copy corruptions,frontier gap,sync poison,manifest damage,multiwrap/continue/reopen\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
